describe('Pinch-to-Zoom on Product Images', () => {
  beforeEach(() => {
    cy.visit('/products');
  });

  it('should enable pinch-to-zoom on product images and allow zooming in and out', () => {
    // Verify initial state: product image is visible without zoom
    cy.get('[data-testid="product-image"]').should('be.visible');
    cy.get('[data-testid="product-image"]').should('have.css', 'width', '100%');

    // Intercept the zoom event
    cy.intercept('POST', '/api/zoom/pinch').as('zoomPinch');

    // Perform pinch-to-zoom gesture
    cy.get('[data-testid="product-image"]').trigger('touchmove', {
      deltaX: 50,
      deltaY: 50,
      scale: 1.2,
      rotation: 0,
      touches: [{ identifier: 1, clientX: 100, clientY: 100 }]
    });

    // Wait for zoom API call
    cy.wait('@zoomPinch');

    // Verify zoom state
    cy.get('[data-testid="product-image"]').should('have.css', 'width', '120%');
    cy.get('[data-testid="product-image"]').should('have.css', 'height', '120%');

    // Verify zoom controls are visible
    cy.get('[data-testid="zoom-controls"]').should('be.visible');

    // Verify zoom level is displayed
    cy.get('[data-testid="zoom-level"]').should('contain', '120%');

    // Verify zoomed image is still clickable
    cy.get('[data-testid="product-image"]').click();

    // Verify navigation to product details
    cy.url().should('include', '/products/123');
  });

  it('should disable zoom when image is already at maximum zoom level', () => {
    // Intercept zoom API call
    cy.intercept('POST', '/api/zoom/pinch').as('zoomPinch');

    // Zoom in to maximum level
    cy.get('[data-testid="product-image"]').trigger('touchmove', {
      deltaX: 50,
      deltaY: 50,
      scale: 2,
      rotation: 0,
      touches: [{ identifier: 1, clientX: 100, clientY: 100 }]
    });

    // Wait for zoom API call
    cy.wait('@zoomPinch');

    // Verify zoom level is at maximum
    cy.get('[data-testid="zoom-level"]').should('contain', '200%');

    // Attempt to zoom in further
    cy.get('[data-testid="product-image"]').trigger('touchmove', {
      deltaX: 50,
      deltaY: 50,
      scale: 3,
      rotation: 0,
      touches: [{ identifier: 1, clientX: 100, clientY: 100 }]
    });

    // Wait for zoom API call
    cy.wait('@zoomPinch');

    // Verify zoom level remains at maximum
    cy.get('[data-testid="zoom-level"]').should('contain', '200%');

    // Verify zoom controls are still visible
    cy.get('[data-testid="zoom-controls"]').should('be.visible');

    // Verify zoom controls are disabled
    cy.get('[data-testid="zoom-controls"]').should('have.css', 'opacity', '0.5');

    // Verify zoomed image is still clickable
    cy.get('[data-testid="product-image"]').click();

    // Verify navigation to product details
    cy.url().should('include', '/products/123');
  });
});
